Here is the commit message:
accel/amdxdna: Hold mm structure across
 iommu_sva_unbind_device()

Some tests trigger a crash in iommu_sva_unbind_device() due to
accessing iommu_mm after the associated mm structure has been
freed.

Fix this by taking an explicit reference to the mm structure
after successfully binding the device, and releasing it only
after the device is unbound. This ensures the mm remains valid
for the entire SVA bind/unbind lifetime.

Fixes: be462c97b7df ("accel/amdxdna: Add hardware context")
Reviewed-by: Mario Limonciello (AMD) <superm1@kernel.org>
Signed-off-by: Lizhi Hou <lizhi.hou@amd.com>
Link: https://patch.msgid.link/20260128002356.1858122-1-lizhi.hou@amd.com

Here is the root cause:
The driver did not take an explicit reference to the mm_struct after successfully binding the SVA device. As a result, the mm could be freed before iommu_sva_unbind_device() completes its operation, causing a use-after-free when accessing iommu_mm.

Here is the patch:

 static int amdxdna_drm_open(struct drm_device *ddev, struct drm_file *filp)
 {
 	struct amdxdna_dev *xdna = to_xdna_dev(ddev);
 	struct amdxdna_client *client;
 	int ret;

 	client = kzalloc(sizeof(*client), GFP_KERNEL);
 	if (!client)
 		return -ENOMEM;

 	client->pid = pid_nr(rcu_access_pointer(filp->pid));
 	client->xdna = xdna;

 	client->sva = iommu_sva_bind_device(xdna->ddev.dev, current->mm);
 	if (IS_ERR(client->sva)) {
 		ret = PTR_ERR(client->sva);
 		XDNA_ERR(xdna, "SVA bind device failed, ret %d", ret);
 		goto failed;
 	}
 	client->pasid = iommu_sva_get_pasid(client->sva);
 	if (client->pasid == IOMMU_PASID_INVALID) {
 		XDNA_ERR(xdna, "SVA get pasid failed");
 		ret = -ENODEV;
 		goto unbind_sva;
 	}
+	client->mm = current->mm;
+	mmgrab(client->mm);
 	init_srcu_struct(&client->hwctx_srcu);
 	xa_init_flags(&client->hwctx_xa, XA_FLAGS_ALLOC);
 	mutex_init(&client->mm_lock);

 	mutex_lock(&xdna->dev_lock);
 	list_add_tail(&client->node, &xdna->client_list);
 	mutex_unlock(&xdna->dev_lock);

 	filp->driver_priv = client;
 	client->filp = filp;

 	XDNA_DBG(xdna, "pid %d opened", client->pid);
 	return 0;

 unbind_sva:
 	iommu_sva_unbind_device(client->sva);
 failed:
 	kfree(client);

 	return ret;
 }

 static void amdxdna_client_cleanup(struct amdxdna_client *client)
 {
 	list_del(&client->node);
 	amdxdna_hwctx_remove_all(client);
 	xa_destroy(&client->hwctx_xa);
 	cleanup_srcu_struct(&client->hwctx_srcu);
 	mutex_destroy(&client->mm_lock);

 	if (client->dev_heap)
 		drm_gem_object_put(to_gobj(client->dev_heap));

 	iommu_sva_unbind_device(client->sva);
+	mmdrop(client->mm);

 	kfree(client);
 }



